import csv, collections
rev = list(csv.DictReader(open('letter_line_review.csv', newline='')))
inp = {r['line_id']: r for r in csv.DictReader(open('input/letter_lines.csv', newline=''))}
subjects = ['right_of_first_refusal','children_named','overnight_stays','addressee','inconsistent_accounts','concern','behavioural_plan','request','enclosure','tone','sender_signature','salutation','copies','delivery']
for subj in subjects:
    print(f'### {subj}')
    pairs = collections.defaultdict(list)
    for r in rev:
        if inp[r['line_id']]['subject'] == subj:
            pairs[inp[r['line_id']]['position']].append(r)
    for pos, items in sorted(pairs.items()):
        verdicts = collections.Counter(i['verdict'] for i in items)
        sample = items[0]['line_id']
        print(f"{pos} | {dict(verdicts)} | ex={sample}: {inp[sample]['wording'][:100]}")
PY
